/*
Day #10/24: Frustum
https://openprocessing.org/sketch/2393761
https://mathober.com/
https://openprocessing.org/curation/87980
*/

let S;

function setup() {
  createCanvas(windowWidth, windowHeight);
	background(0, 0, 8);
	describe("net of frustum: circle(s), arc(s), circle(s)");

  noFill();
	stroke("silver");
  strokeWeight(2);
	S = max(width, height);
  loop();
}

function draw() {
	background("rgb(0, 0, 8)");

	const d1 = noisom(S/5, S/8);
	const u1 = PI*d1;
	const d2 = noisom(S/8, S/12);
	const u2 = PI*d2;

	const d = noisom(S/6, S/3)
	const u = PI*S;
	const da = ((u1+u2)/2)/u*PI;
	const a1 = HALF_PI - da;
	const r1 = S/2-d/2;
	const p1 = {x: cos(a1)*r1, y: sin(a1)*r1}
	const a2 = HALF_PI + da;
	const r2 = S/2+d/2;
	const p2 = {x: cos(a2)*r2, y: sin(a2)*r2}

	/*
	stroke("cyan");
	arc(width/2, 0, r1+r1, r1+r1, a1, a2)
	stroke("purple");
	arc(width/2, 0, r2+r2, r2+r2, a1, a2)
	stroke("blue")
	line(width/2+p1.x, p1.y, width/2-p2.x, p2.y)
	line(width/2-p1.x, p1.y, width/2+p2.x, p2.y)
	*/

	const df = 6 / (r2-r1);
	for (let f = 0; f <= 1; f += df) {
		stroke(lerpColor(color("cyan"), color("purple"), 1-f));
		const r = map(f, 0, 1, r1, r2);
		arc(width/2, 0, r+r, r+r, a1, a2)
	}

	stroke("cyan");
	mcircle(width/2, height*1/4, d2)
	stroke("purple");
	mcircle(width/2, height*3/4, d1)

  // // noLoop() removed for animation
}

function mcircle(x, y, d) {
	for (let dd = d; dd > 0; dd -= 10) {
		circle(x, y, dd);
	}
}

function noisom(v1, v2) {
	if (v1>v2) [v1, v2] = [v2, v1];
	const n = noise(v1, v2, frameCount/123);
	return v1+n*(v2-v1);
}

function mouseClicked() {
  if (mouseButton === LEFT) setup();
}
